const K=0.15,R=0.16,H=3,MAX=60,TOL=1e-3;
const S={corner:[2.5,0.3],steep:[0.5,1.5],shallow:[2.8,0.05]};
const loss=(x,y)=>0.5*x*x+y*y;
const ball=p=>({x:p[0],y:p[1],n:0,path:[p]});
const fresh=inp=>{const p=S[inp.start]||S.corner;return{on:false,a:ball(p),b:ball(p)};};
const word=b=>Math.abs(b.x)>H||Math.abs(b.y)>H?'diverged':loss(b.x,b.y)<TOL?'converged':b.n>=MAX?'stopped':'';
function move(b,lr){if(word(b))return b;const x=b.x-lr*b.x,y=b.y-lr*2*b.y;return{...b,x,y,n:b.n+1,path:b.path.concat([[x,y]])};}
const adv=(s,inp)=>({...s,a:move(s.a,inp.lrA),b:move(s.b,inp.lrB)});
const done=s=>word(s.a)&&word(s.b);
export function initialState({inputs}){return fresh(inputs);}
export function reduce({state:s,event:e,inputs}){
if(e.type==='step'){if(!s.on||e.tick%6)return s;const t=adv(s,inputs);return done(t)?{...t,on:false}:t;}
if(e.type==='parameter')return e.parameter==='start'?fresh({...inputs,start:e.value}):s;
if(e.type!=='action')return s;
if(e.action==='run')return done(s)?s:{...s,on:true};
if(e.action==='pause')return{...s,on:false};
if(e.action==='stepOnce')return adv({...s,on:false},inputs);
if(e.action==='rerun')return fresh(inputs);
return s;}
const clip=v=>Math.max(-H,Math.min(H,v));
const lift=p=>{const x=clip(p[0]),y=clip(p[1]);return[x,K*loss(x,y)+0.04,y];};
const place=b=>{const q=lift([b.x,b.y]);return[q[0],q[1]-0.04+R,q[2]];};
export function evaluate({inputs,state}){
const s=state||fresh(inputs),st=b=>word(b)||(s.on?'running':'paused');
return{nodes:{ballA:{position:place(s.a)},ballB:{position:place(s.b)},trailA:{points:s.a.path.map(lift)},trailB:{points:s.b.path.map(lift)}},
readouts:{lossA:loss(s.a.x,s.a.y),lossB:loss(s.b.x,s.b.y),statusA:st(s.a),statusB:st(s.b),stepsA:s.a.n,stepsB:s.b.n}};}
